                "type": "string"
            },
            "title": "Channel trait",
            "type": "array"
        },
        "traits_trait_id_json": {
            "$schema": "http://json-schema.org/draft-04/schema#",
            "description": "A globally unique identifier of the content in the ANS repository.",
            "title": "Globally Unique ID trait",
            "type": "string"
        },
        "traits_trait_subtype_json": {
            "$schema": "http://json-schema.org/draft-04/schema#",
